css2:
footer .sL .sl-tt{--sb:#111111}
.mnMob .mSoc{gap:6px;flex-wrap:wrap;left:0;right:0;width:100%}
.mnMob .mSoc .tIc{width:34px;height:34px;border-radius:10px;background:rgba(8,16,43,.03);border:1px solid rgba(8,16,43,.1);box-shadow:0 1px 2px rgba(8,16,43,.06);color:var(--bodyC,inherit);line-height:0;transition:transform .2s ease,background .2s ease,border-color .2s ease,color .2s ease,box-shadow .2s ease}
.mnMob .mSoc .tIc::after{display:none}
.mnMob .mSoc .tIc svg{width:18px;height:18px;opacity:1;fill:currentColor;stroke:none}
.mnMob .mSoc .tIc svg *{fill:currentColor;stroke:none}
.mnMob .mSoc .tIc svg .svgC{fill:var(--sb,currentColor)}
.mnMob .mSoc .tIc:hover,.mnMob .mSoc .tIc:focus-visible{transform:translateY(-2px);background:var(--sb,var(--linkC));border-color:transparent;color:#fff;box-shadow:0 6px 14px rgba(8,16,43,.15)}
.mnMob .mSoc .tIc:hover svg .svgC,.mnMob .mSoc .tIc:focus-visible svg .svgC{fill:currentColor}
.drK .mnMob .mSoc .tIc{background:rgba(255,255,255,.04);border-color:rgba(255,255,255,.12);color:inherit;box-shadow:none}
.drK .mnMob .mSoc .tIc:hover,.drK .mnMob .mSoc .tIc:focus-visible{background:var(--sb,var(--linkC));border-color:transparent;color:#fff;box-shadow:0 6px 14px rgba(0,0,0,.35)}
.mSoc [aria-label=Facebook i]{--sb:#1877F2} .mSoc [aria-label=Telegram i]{--sb:#229ED9} .mSoc [aria-label=Instagram i]{--sb:#E1306C} .mSoc [aria-label=Twitter i],.mSoc [aria-label=X i]{--sb:#14171A} .mSoc [aria-label=Whatsapp i]{--sb:#25D366} .mSoc [aria-label=Youtube i]{--sb:#FF0000} .mSoc [aria-label=Tiktok i]{--sb:#111111} .mSoc [aria-label=Pinterest i]{--sb:#E60023} .mSoc [aria-label=LinkedIn i]{--sb:#0A66C2}
.mnMob .mSoc [aria-label=Instagram i]:hover,.mnMob .mSoc [aria-label=Instagram i]:focus-visible{background:linear-gradient(45deg,#F58529,#DD2A7B 55%,#8134AF)}
.drK .mnMob .mSoc [aria-label=Twitter i]:hover,.drK .mnMob .mSoc [aria-label=X i]:hover{background:#fff;color:#14171A}
@media (prefers-reduced-motion:reduce){.mnMob .mSoc .tIc{transition:none}.mnMob .mSoc .tIc:hover{transform:none}}
